package com.bankpli.javabank.customer;import static org.junit.jupiter.api.Assertions.*;import java.time.LocalDate;import org.junit.jupiter.api.Test;
class CustomerValidatorTest{private final CustomerValidator v=new CustomerValidator();private CustomerRequest valid(){return new CustomerRequest("Mr","John","Smith","a@b.com","(555) 123-4567",LocalDate.of(1990,1,1),700);}@Test void acceptsValid(){assertTrue(v.validate(valid()).isEmpty());}@Test void rejectsDocumentedInvalidInputs(){assertFalse(v.validate(new CustomerRequest("","","Smith","a@b.com","5551234567",LocalDate.of(1990,1,1),700)).isEmpty());assertFalse(v.validate(new CustomerRequest("","John3","Smith","a@b.com","5551234567",LocalDate.of(1990,1,1),700)).isEmpty());assertFalse(v.validate(new CustomerRequest("","John","O'Brien","a@b.com","5551234567",LocalDate.of(1990,1,1),700)).isEmpty());assertFalse(v.validate(new CustomerRequest("","John","Smith","abc.def@x","5551234567",LocalDate.of(1990,1,1),700)).isEmpty());assertFalse(v.validate(new CustomerRequest("","John","Smith","a@b.com","12345",LocalDate.of(1990,1,1),700)).isEmpty());}}
